/*@@PART js/strings.js@@*/
/* Russian counts agree with the number they follow, and the interface was
   writing "+1 очков" — which is the shape you get from bolting a plural onto a
   number and hoping. One form for 1, another for 2-4, a third for 5 and up, and
   the teens are all the third one regardless of their last digit.

   Used by every line that prints a count into Russian. English needs none of
   this, which is why it lives here rather than in the shared code. */
function ruPlural(n, one, few, many){
  const a=Math.abs(Math.round(n))%100, b=a%10;
  if(a>10 && a<20) return many;
  if(b===1) return one;
  if(b>=2 && b<=4) return few;
  return many;
}
function ruPts(n){ return n+' '+ruPlural(n, 'очко', 'очка', 'очков'); }
function ruGames(n){ return n+' '+ruPlural(n, 'игру', 'игры', 'игр'); }
function ruTeams(n){ return n+' '+ruPlural(n, 'команда', 'команды', 'команд'); }
function ruDays(n){ return n+' '+ruPlural(n, 'день', 'дня', 'дней'); }
// Slots and seats come one at a time in four of the seven regions — NAW, Asia,
// the Middle East and Oceania each carry a single Global Championship place —
// so "1 слотов" is a line the interface actually printed.
function ruSlots(n){ return n+' '+ruPlural(n, 'слот', 'слота', 'слотов'); }
function ruSlotsIn(n){ return n+' '+ruPlural(n, 'слоте', 'слотах', 'слотах'); }
function ruPlaces(n){ return n+' '+ruPlural(n, 'место', 'места', 'мест'); }
/* A placement is said out loud, and out loud it is "top 25".

   Nobody in this scene says "hash twenty five". They say top 25, in Russian as
   well as English, and it is the same word in both - which is why one helper
   covers the pair of dictionaries rather than a phrase written twice.

   Two of them because a sentence has a beginning: "Топ 25 из 150. Красиво" and
   "Мейджор 1: топ 25". The number is the same, the capital is not.

   What keeps its hash is a rank column in a table, where the number is the row
   rather than a statement about the night - a column reading top 3 / top 4 /
   top 5 down its length is one word printed forty times. */
function ccTop(n){ return (LANG==='ru' ? 'топ ' : 'top ')+n; }
function ccOrdEn(n){ const v=n%100; return n+((v>=11&&v<=13)?'th':(['th','st','nd','rd'][n%10]||'th')); }
function ccTopC(n){ return (LANG==='ru' ? 'Топ ' : 'Top ')+n; }
